1	package fleet
2	
3	import (
4		"errors"
5		"sort"
6		"sync"
7		"time"
8	)
9	
10	var (
11		ErrDeviceNotFound  = errors.New("device not found")
12		ErrBatchConflict   = errors.New("batch conflicts with stored events")
13		ErrRuleNotFound    = errors.New("rule not found")
14		ErrAlertNotFound   = errors.New("alert not found")
15		ErrRuleConflict    = errors.New("rule already exists")
16		ErrVersionConflict = errors.New("rule version conflict")
17		ErrInvalidRule     = errors.New("invalid rule")
18	)
19	
20	// Rule is a per-device threshold rule. It judges only samples accepted while
21	// enabled; it never backfills history. Device and ID are immutable after
22	// creation. Version starts at 1 and bumps on every successful update.
23	type Rule struct {
24		ID        string    `json:"id"`
25		Metric    string    `json:"metric"`
26		Trigger   float64   `json:"trigger"`
27		Recover   float64   `json:"recover"`
28		Enabled   bool      `json:"enabled"`
29		Version   int64     `json:"version"`
30		CreatedAt time.Time `json:"createdAt"`
31		UpdatedAt time.Time `json:"updatedAt"`
32	}
33	
34	// Alert is one threshold crossing. It retains the rule version and the
35	// metric/thresholds in force when it fired. A natural recovery records the
36	// recovery sample's sequence, value and observed time; an end caused by a rule
37	// update records the server time and reason instead.
38	type Alert struct {
39		ID                int64      `json:"id"`
40		RuleID            string     `json:"ruleId"`
41		RuleVersion       int64      `json:"ruleVersion"`
42		Metric            string     `json:"metric"`
43		Trigger           float64    `json:"trigger"`
44		Recover           float64    `json:"recover"`
45		Status            string     `json:"status"` // "active" | "ended"
46		TriggerSequence   int64      `json:"triggerSequence"`
47		TriggerValue      float64    `json:"triggerValue"`
48		TriggerObservedAt time.Time  `json:"triggerObservedAt"`
49		RecoverSequence   *int64     `json:"recoverSequence,omitempty"`
50		RecoverValue      *float64   `json:"recoverValue,omitempty"`
51		RecoverObservedAt *time.Time `json:"recoverObservedAt,omitempty"`
52		EndedAt           *time.Time `json:"endedAt,omitempty"`
53		EndReason         string     `json:"endReason,omitempty"` // "recovered" | "rule_changed"
54		AcknowledgedAt    *time.Time `json:"acknowledgedAt,omitempty"`
55	}
56	
57	const (
58		alertStatusActive    = "active"
59		alertStatusEnded     = "ended"
60		endReasonRecovered   = "recovered"
61		endReasonRuleChanged = "rule_changed"
62	)
63	
64	// ruleState pairs a rule with the id of its currently active alert (0 when
65	// none).
66	type ruleState struct {
67		rule          Rule
68		activeAlertID int64
69	}
