166	func (s *Store) Register(id, site string) (Device, bool, error) {
167		s.mu.Lock()
168		defer s.mu.Unlock()
169		if state, ok := s.devices[id]; ok {
170			return cloneDevice(state.device), false, nil
171		}
172		now := s.now().UTC()
173		device := Device{ID: id, Site: site, RegisteredAt: now, LastSeenAt: now}
174		if s.wal != nil {
175			if err := s.wal.appendRecord(recRegister, walRegister{
176				ID: id, Site: site, RegisteredAt: now, LastSeenAt: now,
177			}); err != nil {
178				return Device{}, false, storageUnavailable(err)
179			}
180		}
181		s.devices[id] = &deviceState{
182			device:  device,
183			byEvent: make(map[string]int64),
184			batches: make(map[string]storedBatch),
185			rules:   make(map[string]*ruleState),
186		}
187		return cloneDevice(device), true, nil
188	}
