190	// RecordTelemetry stores a live telemetry sample in the device history. The
191	// sample has no caller-supplied eventId, so it is never a replay duplicate; its
192	// observed time is the server receive time.
193	func (s *Store) RecordTelemetry(id string, values map[string]float64) (Device, error) {
194		s.mu.Lock()
195		defer s.mu.Unlock()
196		state, ok := s.devices[id]
197		if !ok {
198			return Device{}, ErrDeviceNotFound
199		}
200		now := s.now().UTC()
201		sequence := int64(len(state.events)) + 1
202		eval := newAlertEvaluator(state)
203		eval.evaluate(sequence, now, values)
204		if s.wal != nil {
205			if err := s.wal.appendRecord(recTelemetry, walTelemetry{
206				DeviceID:   id,
207				Sequence:   sequence,
208				ObservedAt: now,
209				Values:     values,
210				Alerts:     eval.created,
211				Ended:      eval.ended,
212			}); err != nil {
213				return Device{}, storageUnavailable(err)
214			}
215		}
216		state.events = append(state.events, Event{
217			Sequence:   sequence,
218			ObservedAt: now,
219			Values:     cloneTelemetry(values),
220		})
221		state.device.LastSeenAt = now
222		state.device.LastTelemetry = cloneTelemetry(values)
223		eval.commit()
224		return cloneDevice(state.device), nil
225	}
