227	// Replay validates and commits a batch atomically. repeat is true when the
228	// batchId was already committed with identical content and the first receipt
229	// is returned unchanged. It returns ErrDeviceNotFound for an unknown device and
230	// ErrBatchConflict when any sample clashes with an existing eventId or the
231	// batchId was previously committed with different ordered content; in either
232	// conflict case no state changes.
233	func (s *Store) Replay(id, batchID string, samples []Sample) (receipt ReplayReceipt, repeat bool, err error) {
234		s.mu.Lock()
235		defer s.mu.Unlock()
236		state, ok := s.devices[id]
237		if !ok {
238			return ReplayReceipt{}, false, ErrDeviceNotFound
239		}
240	
241		if previous, exists := state.batches[batchID]; exists {
242			if !sameOrderedSamples(previous.samples, samples) {
243				return ReplayReceipt{}, false, ErrBatchConflict
244			}
245			return cloneReceipt(previous.receipt), true, nil
246		}
247	
248		// Validate every sample against committed history before appending so a
249		// conflict rolls back without leaving sequences, events or receipts.
250		type plan struct {
251			sample   Sample
252			sequence int64
253			dup      bool
254		}
255		planned := make([]plan, len(samples))
256		nextSequence := int64(len(state.events)) + 1
257		for i, sample := range samples {
258			if sequence, seen := state.byEvent[sample.EventID]; seen {
259				existing := state.events[sequence-1]
260				if !sameInstant(existing.ObservedAt, sample.ObservedAt) ||
261					!sameValues(existing.Values, sample.Values) {
262					return ReplayReceipt{}, false, ErrBatchConflict
263				}
264				planned[i] = plan{sample, sequence, true}
265				continue
266			}
267			planned[i] = plan{sample, nextSequence, false}
268			nextSequence++
269		}
270	
271		// Build the receipt from the plan: only samples that matched a committed
272		// event before this batch are duplicates.
273		receipt = ReplayReceipt{BatchID: batchID, SampleStatus: make([]SampleStatus, 0, len(samples))}
274		for _, entry := range planned {
275			receipt.SampleStatus = append(receipt.SampleStatus, SampleStatus{
276				EventID:   entry.sample.EventID,
277				Sequence:  entry.sequence,
278				Duplicate: entry.dup,
279			})
280			if entry.dup {
281				receipt.Duplicate++
282			} else {
283				receipt.NewCount++
284			}
285		}
286	
287		// Evaluate the batch's new samples against the device's enabled rules, in
288		// array order (which is receive-sequence order). Duplicates never judge,
289		// create, end or refresh alerts. A trigger and a recovery inside one batch
290		// both produce alert changes, all committed together with the batch.
291		eval := newAlertEvaluator(state)
292		for _, entry := range planned {
293			if entry.dup {
294				continue
295			}
296			eval.evaluate(entry.sequence, entry.sample.ObservedAt, entry.sample.Values)
297		}
298	
299		// Durable commit point: the whole batch is one record, synced before any
300		// in-memory state changes and before success is reported. A failure here
301		// leaves sequences, history, receipts, device state and alert changes
302		// untouched.
303		lastNew := -1
304		for i, entry := range planned {
305			if !entry.dup {
306				lastNew = i
307			}
308		}
309		var committedAt time.Time
310		if s.wal != nil {
311			record := walReplay{
312				DeviceID: id,
313				BatchID:  batchID,
314				Samples:  make([]walSample, len(samples)),
315				Receipt:  receipt,
316				Alerts:   eval.created,
317				Ended:    eval.ended,
318			}
319			for i, sample := range samples {
320				record.Samples[i] = walSample{
321					EventID:    sample.EventID,
322					ObservedAt: sample.ObservedAt,
323					Values:     sample.Values,
324				}
325			}
326			if lastNew >= 0 {
327				committedAt = s.now().UTC()
328				record.LastSeenAt = &committedAt
329				record.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
330			}
331			if err := s.wal.appendRecord(recReplay, record); err != nil {
332				return ReplayReceipt{}, false, storageUnavailable(err)
333			}
334		}
335	
336		// Commit: append new samples in array order.
337		for _, entry := range planned {
338			if entry.dup {
339				continue
340			}
341			state.events = append(state.events, Event{
342				Sequence:   entry.sequence,
343				ObservedAt: entry.sample.ObservedAt,
344				Values:     cloneTelemetry(entry.sample.Values),
345			})
346			state.byEvent[entry.sample.EventID] = entry.sequence
347		}
348	
349		committed := make([]Sample, len(samples))
350		copy(committed, samples)
351		for i := range committed {
352			committed[i].Values = cloneTelemetry(samples[i].Values)
353		}
354		state.batches[batchID] = storedBatch{samples: committed, receipt: cloneReceipt(receipt)}
355	
356		if lastNew >= 0 {
357			if s.wal == nil {
358				committedAt = s.now().UTC()
359			}
360			state.device.LastSeenAt = committedAt
361			state.device.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
362		}
363		eval.commit()
364		return receipt, false, nil
365	}
366	
367	func cloneReceipt(receipt ReplayReceipt) ReplayReceipt {
368		receipt.SampleStatus = append([]SampleStatus(nil), receipt.SampleStatus...)
369		return receipt
370	}
