372	// --- rules and alerts -------------------------------------------------------
373	
374	// ruleUpdate carries the mutable fields of a rule update. A nil pointer leaves
375	// the field unchanged.
376	type ruleUpdate struct {
377		Metric  *string
378		Trigger *float64
379		Recover *float64
380		Enabled *bool
381	}
382	
383	// AlertFilter narrows an alert listing. An empty string or nil pointer leaves
384	// that dimension unfiltered.
385	type AlertFilter struct {
386		RuleID       string
387		Status       string
388		Acknowledged *bool
389	}
390	
391	// CreateRule registers a new enabled rule on a device. Version starts at 1.
392	// It returns ErrDeviceNotFound for an unknown device and ErrRuleConflict when
393	// the device already has a rule with that id.
394	func (s *Store) CreateRule(id, ruleID, metric string, trigger, recover float64) (Rule, error) {
395		s.mu.Lock()
396		defer s.mu.Unlock()
397		state, ok := s.devices[id]
398		if !ok {
399			return Rule{}, ErrDeviceNotFound
400		}
401		if _, exists := state.rules[ruleID]; exists {
402			return Rule{}, ErrRuleConflict
403		}
404		now := s.now().UTC()
405		rule := Rule{
406			ID: ruleID, Metric: metric, Trigger: trigger, Recover: recover,
407			Enabled: true, Version: 1, CreatedAt: now, UpdatedAt: now,
408		}
409		if s.wal != nil {
410			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: rule}); err != nil {
411				return Rule{}, storageUnavailable(err)
412			}
413		}
414		state.rules[ruleID] = &ruleState{rule: rule}
415		return cloneRule(rule), nil
416	}
417	
418	// UpdateRule applies a version-checked optimistic update. A version mismatch
419	// returns ErrVersionConflict with state unchanged. Every successful update
420	// bumps the version by one and immediately ends the rule's active alert (if
421	// any) with reason rule_changed; the rule starts again with no active alert.
422	func (s *Store) UpdateRule(id, ruleID string, update ruleUpdate, version int64) (Rule, []*Alert, error) {
423		s.mu.Lock()
424		defer s.mu.Unlock()
425		state, ok := s.devices[id]
426		if !ok {
427			return Rule{}, nil, ErrDeviceNotFound
428		}
429		rs, ok := state.rules[ruleID]
430		if !ok {
431			return Rule{}, nil, ErrRuleNotFound
432		}
433		if rs.rule.Version != version {
434			return Rule{}, nil, ErrVersionConflict
435		}
436	
437		updated := rs.rule
438		if update.Metric != nil {
439			updated.Metric = *update.Metric
440		}
441		if update.Trigger != nil {
442			updated.Trigger = *update.Trigger
443		}
444		if update.Recover != nil {
445			updated.Recover = *update.Recover
446		}
447		if update.Enabled != nil {
448			updated.Enabled = *update.Enabled
449		}
450		if updated.Recover >= updated.Trigger {
451			return Rule{}, nil, ErrInvalidRule
452		}
453	
454		// End the active alert of the old version before publishing the new one.
455		var ended []*Alert
456		if rs.activeAlertID != 0 {
457			alert := cloneAlert(*state.alerts[rs.activeAlertID-1])
458			alert.Status = alertStatusEnded
459			alert.EndReason = endReasonRuleChanged
460			now := s.now().UTC()
461			alert.EndedAt = &now
462			ended = append(ended, &alert)
463			rs.activeAlertID = 0
464		}
465	
466		updated.Version++
467		updated.UpdatedAt = s.now().UTC()
468	
469		if s.wal != nil {
470			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: updated, Ended: ended}); err != nil {
471				return Rule{}, nil, storageUnavailable(err)
472			}
473		}
474		rs.rule = updated
475		for _, alert := range ended {
476			state.alerts[alert.ID-1] = alert
477		}
478		return cloneRule(updated), cloneAlerts(ended), nil
479	}
480	
481	// GetRule returns one rule.
482	func (s *Store) GetRule(id, ruleID string) (Rule, error) {
483		s.mu.RLock()
484		defer s.mu.RUnlock()
485		state, ok := s.devices[id]
486		if !ok {
487			return Rule{}, ErrDeviceNotFound
488		}
489		rs, ok := state.rules[ruleID]
490		if !ok {
491			return Rule{}, ErrRuleNotFound
492		}
493		return cloneRule(rs.rule), nil
494	}
495	
496	// ListRules returns a device's rules, ordered by rule id.
497	func (s *Store) ListRules(id string) ([]Rule, error) {
498		s.mu.RLock()
499		defer s.mu.RUnlock()
500		state, ok := s.devices[id]
501		if !ok {
502			return nil, ErrDeviceNotFound
503		}
504		rules := make([]Rule, 0, len(state.rules))
505		for _, rs := range state.rules {
506			rules = append(rules, cloneRule(rs.rule))
507		}
508		sort.Slice(rules, func(i, j int) bool { return rules[i].ID < rules[j].ID })
509		return rules, nil
510	}
