512	// AckAlert records the server time of the first acknowledgment. Repeated
513	// acknowledgments keep the original time and write nothing. It returns
514	// ErrDeviceNotFound for an unknown device and ErrAlertNotFound for an unknown
515	// alert id.
516	func (s *Store) AckAlert(id string, alertID int64) (Alert, error) {
517		s.mu.Lock()
518		defer s.mu.Unlock()
519		state, ok := s.devices[id]
520		if !ok {
521			return Alert{}, ErrDeviceNotFound
522		}
523		if alertID < 1 || int(alertID) > len(state.alerts) {
524			return Alert{}, ErrAlertNotFound
525		}
526		alert := state.alerts[alertID-1]
527		if alert.AcknowledgedAt != nil {
528			return cloneAlert(*alert), nil
529		}
530		now := s.now().UTC()
531		if s.wal != nil {
532			if err := s.wal.appendRecord(recAlertAck, walAlertAck{
533				DeviceID: id, AlertID: alertID, AcknowledgedAt: now,
534			}); err != nil {
535				return Alert{}, storageUnavailable(err)
536			}
537		}
538		alert.AcknowledgedAt = &now
539		return cloneAlert(*alert), nil
540	}
541	
542	// ListAlerts returns a device's alerts with the given filters, ordered by
543	// alert id.
544	func (s *Store) ListAlerts(id string, filter AlertFilter) ([]Alert, error) {
545		s.mu.RLock()
546		defer s.mu.RUnlock()
547		state, ok := s.devices[id]
548		if !ok {
549			return nil, ErrDeviceNotFound
550		}
551		if filter.RuleID != "" {
552			if _, ok := state.rules[filter.RuleID]; !ok {
553				return nil, ErrRuleNotFound
554			}
555		}
556		alerts := make([]Alert, 0, len(state.alerts))
557		for _, alert := range state.alerts {
558			if filter.RuleID != "" && alert.RuleID != filter.RuleID {
559				continue
560			}
561			if filter.Status != "" && alert.Status != filter.Status {
562				continue
563			}
564			if filter.Acknowledged != nil {
565				acknowledged := alert.AcknowledgedAt != nil
566				if *filter.Acknowledged != acknowledged {
567					continue
568				}
569			}
570			alerts = append(alerts, cloneAlert(*alert))
571		}
572		return alerts, nil
573	}
574	
575	// alertEvaluator applies accepted samples to a device's enabled rules without
576	// mutating state until commit. It tracks which rule currently has an active
577	// alert so a trigger and a recovery inside the same batch are both handled in
578	// order.
579	type alertEvaluator struct {
580		state        *deviceState
581		activeByRule map[string]int64 // ruleID -> active alert id (0 when none)
582		created      []*Alert
583		ended        []*Alert
584		nextID       int64
585	}
586	
587	func newAlertEvaluator(state *deviceState) *alertEvaluator {
588		eval := &alertEvaluator{
589			state:        state,
590			activeByRule: make(map[string]int64, len(state.rules)),
591			nextID:       int64(len(state.alerts)) + 1,
592		}
593		for id, rs := range state.rules {
594			eval.activeByRule[id] = rs.activeAlertID
595		}
596		return eval
597	}
598	
599	// evaluate judges one accepted sample. A value at or above the trigger opens
600	// an alert (or keeps the existing one); a value at or below the recovery
601	// threshold ends the active alert; anything in between or a missing metric
602	// leaves state unchanged.
603	func (eval *alertEvaluator) evaluate(seq int64, observedAt time.Time, values map[string]float64) {
604		for _, rs := range eval.state.rules {
605			if !rs.rule.Enabled {
606				continue
607			}
608			value, ok := values[rs.rule.Metric]
609			if !ok {
610				continue
611			}
612			activeID := eval.activeByRule[rs.rule.ID]
613			if value >= rs.rule.Trigger && activeID == 0 {
614				alert := &Alert{
615					ID:                eval.nextID,
616					RuleID:            rs.rule.ID,
617					RuleVersion:       rs.rule.Version,
618					Metric:            rs.rule.Metric,
619					Trigger:           rs.rule.Trigger,
620					Recover:           rs.rule.Recover,
621					Status:            alertStatusActive,
622					TriggerSequence:   seq,
623					TriggerValue:      value,
624					TriggerObservedAt: observedAt,
625				}
626				eval.nextID++
627				eval.created = append(eval.created, alert)
628				eval.activeByRule[rs.rule.ID] = alert.ID
629			} else if value <= rs.rule.Recover && activeID != 0 {
630				var source *Alert
631				if activeID <= int64(len(eval.state.alerts)) {
632					source = eval.state.alerts[activeID-1]
633				} else {
634					source = eval.created[activeID-int64(len(eval.state.alerts))-1]
635				}
636				alert := cloneAlert(*source)
637				alert.Status = alertStatusEnded
638				alert.EndReason = endReasonRecovered
639				alert.RecoverSequence = &seq
640				alert.RecoverValue = &value
641				alert.RecoverObservedAt = &observedAt
642				eval.ended = append(eval.ended, &alert)
643				eval.activeByRule[rs.rule.ID] = 0
644			}
645		}
646	}
647	
648	// commit publishes the planned alert changes to the device state.
649	func (eval *alertEvaluator) commit() {
650		applyAlertChanges(eval.state, eval.created, eval.ended)
651	}
652	
653	// applyAlertChanges appends created alerts and replaces ended ones, keeping
654	// each rule's active-alert pointer in sync. It is shared by live evaluation
655	// and WAL recovery.
656	func applyAlertChanges(state *deviceState, created, ended []*Alert) {
657		for _, alert := range created {
658			state.alerts = append(state.alerts, alert)
659			if rs, ok := state.rules[alert.RuleID]; ok {
660				rs.activeAlertID = alert.ID
661			}
662		}
663		for _, alert := range ended {
664			state.alerts[alert.ID-1] = alert
665			if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
666				rs.activeAlertID = 0
667			}
668		}
669	}
670	
671	func cloneRule(rule Rule) Rule {
672		return rule
673	}
674	
675	func cloneAlert(alert Alert) Alert {
676		if alert.RecoverSequence != nil {
677			seq := *alert.RecoverSequence
678			alert.RecoverSequence = &seq
679		}
680		if alert.RecoverValue != nil {
681			value := *alert.RecoverValue
682			alert.RecoverValue = &value
683		}
684		if alert.RecoverObservedAt != nil {
685			t := *alert.RecoverObservedAt
686			alert.RecoverObservedAt = &t
687		}
688		if alert.EndedAt != nil {
689			t := *alert.EndedAt
690			alert.EndedAt = &t
691		}
692		if alert.AcknowledgedAt != nil {
693			t := *alert.AcknowledgedAt
694			alert.AcknowledgedAt = &t
695		}
696		return alert
697	}
698	
699	func cloneAlerts(alerts []*Alert) []*Alert {
700		if alerts == nil {
701			return nil
702		}
703		cloned := make([]*Alert, len(alerts))
704		for i, alert := range alerts {
705			c := cloneAlert(*alert)
706			cloned[i] = &c
707		}
708		return cloned
709	}
710	
711	// History returns one page of a device's event history. afterIndex is the first
712	// 0-based event slot to scan (0 for the first page); limit caps the number of
713	// matching events returned. bound pins the scan to sequences no larger than
714	// bound; a zero bound means "current maximum", which is then returned so
715	// callers can pin subsequent pages. nextIndex is the slot a following page
716	// should start at when hasMore is true. Concurrent writes therefore cannot
717	// skip or duplicate rows within a paged walk.
718	func (s *Store) History(id string, filter HistoryFilter, afterIndex, bound int64, limit int) (events []Event, appliedBound, nextIndex int64, hasMore bool, err error) {
719		s.mu.RLock()
720		defer s.mu.RUnlock()
721		state, ok := s.devices[id]
722		if !ok {
723			return nil, 0, 0, false, ErrDeviceNotFound
724		}
725		highWater := int64(len(state.events))
726		if bound == 0 {
727			bound = highWater
728		}
729		events = make([]Event, 0, limit)
730		for index := afterIndex; index < bound; index++ {
731			event := state.events[index]
732			if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
733				continue
734			}
735			if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
736				continue
737			}
738			if len(events) < limit {
739				events = append(events, cloneEvent(event))
740				continue
741			}
742			// This match belongs to the next page; resume scanning here so rows in
743			// the gap are never examined twice.
744			return events, bound, index, true, nil
745		}
746		return events, bound, bound, false, nil
747	}
748	
749	func (s *Store) Snapshot() []Device {
750		s.mu.RLock()
751		defer s.mu.RUnlock()
752		result := make([]Device, 0, len(s.devices))
753		for _, state := range s.devices {
754			result = append(result, cloneDevice(state.device))
755		}
756		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
757		return result
758	}
759	
760	func cloneDevice(device Device) Device {
761		device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
762		return device
763	}
764	
765	func cloneEvent(event Event) Event {
766		event.Values = cloneTelemetry(event.Values)
767		return event
768	}
769	
770	func cloneTelemetry(values map[string]float64) map[string]float64 {
771		if values == nil {
772			return nil
773		}
774		cloned := make(map[string]float64, len(values))
775		for key, value := range values {
776			cloned[key] = value
777		}
778		return cloned
779	}
780	
781	// sameInstant compares times as UTC instants.
782	func sameInstant(a, b time.Time) bool {
783		return a.UTC().Equal(b.UTC())
784	}
785	
786	// sameValues compares metric maps by key and value.
787	func sameValues(a, b map[string]float64) bool {
788		if len(a) != len(b) {
789			return false
790		}
791		for key, value := range a {
792			other, ok := b[key]
793			if !ok || value != other {
794				return false
795			}
796		}
797		return true
798	}
799	
800	// sameOrderedSamples reports whether two batches carry the same samples in the
801	// same order, compared as UTC instants and key/value maps.
802	func sameOrderedSamples(a, b []Sample) bool {
803		if len(a) != len(b) {
804			return false
805		}
806		for i := range a {
807			if a[i].EventID != b[i].EventID ||
808				!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
809				!sameValues(a[i].Values, b[i].Values) {
810				return false
811			}
812		}
813		return true
814	}
815

