223	
224	// walFile is the durable backend. walDurable is the committed WAL length (also
225	// the next frame offset); commitDurable is the journal length. Both files are
226	// truncated back to those offsets before every write, so residue left by a
227	// failed write can never be mistaken for later committed data.
228	type walFile struct {
229		walF          *os.File
230		commitF       *os.File
231		lock          *os.File
232		mu            sync.Mutex
233		walDurable    int64
234		commitDurable int64
235	}
236	
237	func (w *walFile) appendRecord(recType byte, value any) error {
238		frame, err := marshalFrame(recType, value)
239		if err != nil {
240			return err
241		}
242		w.mu.Lock()
243		defer w.mu.Unlock()
244	
245		// Remove residue any previous failed attempt may have left, then phase 1.
246		if err := w.walF.Truncate(w.walDurable); err != nil {
247			return err
248		}
249		if err := pwriteAll(w.walF, frame, w.walDurable); err != nil {
250			return err
251		}
252		if err := w.walF.Sync(); err != nil {
253			return err
254		}
255	
256		// Phase 2: publish the new committed length in the fixed-width journal.
257		newLength := w.walDurable + int64(len(frame))
258		entry := make([]byte, commitEntry)
259		binary.LittleEndian.PutUint64(entry[0:8], uint64(newLength))
260		binary.LittleEndian.PutUint32(entry[8:12], commitCRC(entry[0:8]))
261		if err := w.commitF.Truncate(w.commitDurable); err != nil {
262			return err
263		}
264		if err := pwriteAll(w.commitF, entry, w.commitDurable); err != nil {
265			return err
266		}
267		if err := w.commitF.Sync(); err != nil {
268			return err
269		}
270	
271		w.walDurable = newLength
272		w.commitDurable += int64(commitEntry)
273		return nil
274	}
275	
276	func commitCRC(sizeBytes []byte) uint32 {
277		return crc32.Checksum(sizeBytes, crcTable)
278	}
279	
280	func pwriteAll(f *os.File, buf []byte, offset int64) error {
281		for len(buf) > 0 {
282			n, err := f.WriteAt(buf, offset)
283			if err != nil {
284				return err
285			}
286			buf = buf[n:]
287			offset += int64(n)
288		}
289		return nil
290	}
291	
292	func (w *walFile) Close() error {
293		walErr := w.walF.Close()
294		commitErr := w.commitF.Close()
295		// Closing the lock fd releases the flock; a killed process releases it via
296		// the kernel, so no manual lock cleanup is ever required.
297		lockErr := w.lock.Close()
298		if walErr != nil {
299			return walErr
300		}
301		if commitErr != nil {
302			return commitErr
303		}
304		return lockErr
305	}
306	
307	// NewPersistentStore opens (or creates) a data directory and finishes full
308	// recovery before returning. It fails rather than falling back to memory when
309	// the directory cannot be created, locked, read or written, when another
310	// process already holds the directory, or when committed data is corrupt or
311	// in an unsupported format.
312	func NewPersistentStore(dir string) (_ *Store, err error) {
313		if fi, statErr := os.Stat(dir); statErr == nil {
314			if !fi.IsDir() {
315				return nil, fmt.Errorf("data path %s is not a directory", dir)
316			}
317		} else if !errors.Is(statErr, fs.ErrNotExist) {
318			return nil, fmt.Errorf("cannot access data directory %s: %w", dir, statErr)
319		}
320		if err := os.MkdirAll(dir, 0o755); err != nil {
321			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
322		}
323	
324		// Take the inter-process lock before reading or writing any business data.
325		lockPath := filepath.Join(dir, lockName)
326		lockFile, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
327		if err != nil {
328			return nil, fmt.Errorf("cannot open lock file %s: %w", lockPath, err)
329		}
330		if lockErr := syscall.Flock(int(lockFile.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); lockErr != nil {
331			_ = lockFile.Close()
332			return nil, fmt.Errorf("data directory %s is already in use by another edge-fleet process: %w", dir, lockErr)
333		}
334		handedOff := false
335		defer func() {
336			if !handedOff {
337				_ = lockFile.Close()
338			}
339		}()
340	
341		walPath := filepath.Join(dir, walName)
342		commitPath := filepath.Join(dir, commitName)
343		walF, err := os.OpenFile(walPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
344		if err != nil {
345			return nil, fmt.Errorf("cannot open write-ahead log %s: %w", walPath, err)
346		}
347		commitF, err := os.OpenFile(commitPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
348		if err != nil {
349			_ = walF.Close()
350			return nil, fmt.Errorf("cannot open commit journal %s: %w", commitPath, err)
351		}
352		committed := false
353		defer func() {
354			if !committed {
355				_ = walF.Close()
356				_ = commitF.Close()
357			}
358		}()
359	
360		walInfo, err := walF.Stat()
361		if err != nil {
362			return nil, fmt.Errorf("cannot stat write-ahead log %s: %w", walPath, err)
363		}
364		if walInfo.Size() == 0 {
365			if _, err := walF.WriteAt(walHeader(), 0); err != nil {
366				return nil, fmt.Errorf("cannot initialise write-ahead log %s: %w", walPath, err)
367			}
368			if err := walF.Sync(); err != nil {
369				return nil, fmt.Errorf("cannot flush write-ahead log %s: %w", walPath, err)
370			}
371		}
372	
373		walData, err := io.ReadAll(walF)
374		if err != nil {
375			return nil, fmt.Errorf("cannot read write-ahead log %s: %w", walPath, err)
376		}
377		commitData, err := io.ReadAll(commitF)
378		if err != nil {
379			return nil, fmt.Errorf("cannot read commit journal %s: %w", commitPath, err)
380		}
381		if len(walData) < headerLen || string(walData[0:8]) != walMagic {
382			return nil, fmt.Errorf("write-ahead log %s is corrupt: bad magic header", walPath)
383		}
384		version := binary.LittleEndian.Uint32(walData[8:12])
385		if version != walVersion {
386			return nil, fmt.Errorf("write-ahead log %s uses unsupported format version %d (this server supports %d)", walPath, version, walVersion)
387		}
388		if binary.LittleEndian.Uint32(walData[12:16]) != 0 {
389			return nil, fmt.Errorf("write-ahead log %s is corrupt: bad header flags", walPath)
390		}
391	
392		// Recover the committed WAL length from the fixed-width journal. A short
393		// final block is a torn append from a write that never reported success;
394		// a full block with a bad CRC is committed-data damage. Entries must chain
395		// strictly forward and never point past the WAL. For a fresh journal the
396		// committed prefix is the header itself.
397		walDurable, commitDurable := int64(headerLen), int64(0)
398		for pos := 0; pos < len(commitData); pos += commitEntry {
399			if len(commitData)-pos < commitEntry {
400				break // torn tail: discarded by the truncate below
401			}
402			block := commitData[pos : pos+commitEntry]
403			declared := int64(binary.LittleEndian.Uint64(block[0:8]))
404			if binary.LittleEndian.Uint32(block[8:12]) != commitCRC(block[0:8]) {
405				return nil, fmt.Errorf("commit journal %s is corrupt at byte %d: bad checksum (files left untouched)", commitPath, pos)
406			}
407			if declared <= walDurable || declared > int64(len(walData)) || declared < headerLen {
408				return nil, fmt.Errorf("commit journal %s is corrupt at byte %d: committed length %d is inconsistent", commitPath, pos, declared)
409			}
410			walDurable = declared
411			commitDurable = int64(pos + commitEntry)
412		}
413	
414		// Every byte the journal claims committed must form an exact chain of
415		// valid, in-range frames. Failure here is damage to acknowledged data.
416		type parsedFrame struct {
417			recType byte
418			payload []byte
419		}
420		frames := make([]parsedFrame, 0)
421		pos := headerLen
422		for int64(pos) < walDurable {
423			if pos+5 > len(walData) {
424				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: truncated frame inside committed prefix", walPath, pos)
425			}
426			length := int(binary.LittleEndian.Uint32(walData[pos : pos+4]))
427			frameLen := 5 + length + 4
428			if length > maxRecordPayload || int64(pos+frameLen) > walDurable {
429				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: frame length %d is invalid within the committed prefix", walPath, pos, length)
430			}
431			recType := walData[pos+4]
432			payload := walData[pos+5 : pos+5+length]
433			wantCRC := binary.LittleEndian.Uint32(walData[pos+5+length : pos+frameLen])
434			if crc32.Checksum(walData[pos:pos+5+length], crcTable) != wantCRC {
435				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: frame failed its integrity check (file left untouched)", walPath, pos)
436			}
437			if recType < recInstance || recType > recTaskCancel {
438				return nil, fmt.Errorf("write-ahead log %s uses unsupported record type %d at byte %d", walPath, recType, pos)
439			}
440			frames = append(frames, parsedFrame{recType: recType, payload: payload})
441			pos += frameLen
442		}
443		if int64(pos) != walDurable {
444			return nil, fmt.Errorf("write-ahead log %s is corrupt: committed length %d is not a frame boundary", walPath, walDurable)
445		}
446	
447		// Rebuild relational state from the committed frames, in order.
448		store := NewStore()
449		var instanceID []byte
450		sawInstance := false
451		for i, frame := range frames {
452			switch frame.recType {
453			case recInstance:
454				if sawInstance || i != 0 {
455					return nil, fmt.Errorf("write-ahead log %s is corrupt: instance marker out of place", walPath)
456				}
457				var rec walInstance
458				if err := json.Unmarshal(frame.payload, &rec); err != nil || len(rec.InstanceID) == 0 || len(rec.InstanceID) > 64 {
459					return nil, fmt.Errorf("write-ahead log %s is corrupt: invalid instance marker: %w", walPath, err)
460				}
461				instanceID = rec.InstanceID
462				sawInstance = true
463			case recRegister, recTelemetry, recReplay, recRule, recAlertAck, recConfigPublish, recConfigReceipt,
464				recTaskCreate, recTaskClaim, recTaskReport, recTaskTimeout, recTaskCancel:
465				if !sawInstance {
466					return nil, fmt.Errorf("write-ahead log %s is corrupt: data record precedes instance marker", walPath)
467				}
468				if err := applyRecord(store, frame.recType, frame.payload); err != nil {
469					return nil, fmt.Errorf("write-ahead log %s is corrupt: %w", walPath, err)
470				}
471			}
472		}
473	
474		// Discard unacknowledged residue: bytes from a request that never reached
475		// its journal entry (crash mid-write or a request that returned 503).
476		if int64(len(walData)) != walDurable {
477			if err := walF.Truncate(walDurable); err != nil {
478				return nil, fmt.Errorf("cannot discard unacknowledged tail of %s: %w", walPath, err)
479			}
480			if err := walF.Sync(); err != nil {
481				return nil, fmt.Errorf("cannot flush truncated %s: %w", walPath, err)
482			}
483		}
484		if int64(len(commitData)) != commitDurable {
485			if err := commitF.Truncate(commitDurable); err != nil {
486				return nil, fmt.Errorf("cannot discard torn entry of %s: %w", commitPath, err)
487			}
488			if err := commitF.Sync(); err != nil {
489				return nil, fmt.Errorf("cannot flush truncated %s: %w", commitPath, err)
490			}
491		}
492	
493		wal := &walFile{
494			walF:          walF,
495			commitF:       commitF,
496			lock:          lockFile,
497			walDurable:    walDurable,
498			commitDurable: commitDurable,
499		}
500		if !sawInstance {
501			instanceID = newInstanceID()
502			if err := wal.appendRecord(recInstance, walInstance{InstanceID: instanceID}); err != nil {
503				return nil, fmt.Errorf("cannot write instance marker to %s: %w", walPath, err)
504			}
505		}
506		// Make freshly created directory entries durable as well.
507		if dirFile, err := os.Open(dir); err != nil {
508			return nil, fmt.Errorf("cannot open data directory %s for sync: %w", dir, err)
509		} else {
510			syncErr := syscall.Fsync(int(dirFile.Fd()))
511			_ = dirFile.Close()
512			if syncErr != nil {
513				return nil, fmt.Errorf("cannot flush data directory %s: %w", dir, syncErr)
514			}
515		}
516	
517		store.wal = wal
518		store.iid = instanceID
519		committed = true
520		handedOff = true
521		return store, nil
522	}
523	
524	// Close releases the WAL files and the directory lock.
525	func (s *Store) Close() error {
526		if closer, ok := s.wal.(interface{ Close() error }); ok {
527			return closer.Close()
528		}
529		return nil
530	}
531	
532	func storageUnavailable(err error) error {
533		return fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
534	}
